import Root from "./3Escape Hatches/2SynchronizingwithEffect"
import {HandleInput as Fundamental} from "./2Managing State/3PreserrvingandResetting"
import Sub from "./subReLearn"
import Custom from "./customComponent"
import "./ReLearn.css"

import { useEffect, useRef, useState } from "react"

export default function() {
  const [show, setShow] = useState(false)
  return <>
  <button>{show?"mount":"unmount"}</button>
  <Screen/>
  </>
}

function Screen() {
  useEffect(() => {
    const connection = server()
    connection.connect()
    return () => connection.disconnect()
  })
  return <>
  <h1>testing</h1>
  </>
}

function server() {
  return {
    connect() {console.log("online")},
    disconnect() {console.log("offline")}
  }
}

